<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateAsset\Application\Policy\Allow\UploadContent;

use Throwable;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\UploadContent\TemplateAssetUploadContentAllowDecision;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class IsAuthenticatedUploadContentAllow
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function __invoke(TemplateAssetUploadContentAllowDecision $proposal): TemplateAssetUploadContentAllowDecision
    {
        $this->logDebug("Check IsAuthenticatedUploadContentAllow Template asset");
        $span = $this->startSpan("Check IsAuthenticatedUploadContentAllow Template asset");
        try {
            $userContext = $this->context->getIdentity();
            if ($proposal->isAllowed()) {
                if (! !$userContext->anonymous) {
                    $proposal->deny('Disabled if not IsAuthenticatedUploadContent');
                }
            }
            return $proposal;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
